using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;
using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class ActionSequenceTests {
  GameRuntime game;string directory;int frame;readonly List<float> times=new List<float>();readonly List<string> segments=new List<string>();const string Frames="/tmp/idle-design4-motion";string type;
  [UnitySetUp]public IEnumerator Setup(){directory=Path.Combine(Path.GetTempPath(),"idle-five-actions-"+Guid.NewGuid());Directory.CreateDirectory(directory);GameRuntime.SavePathOverride=Path.Combine(directory,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>NarrativeBridge.Action(s,"name","AURA"));for(int i=0;i<5;i++)game.Act(s=>NarrativeBridge.Action(s,"continue"));game.Act(s=>NarrativeBridge.Action(s,"skip-tutorial"));type=ItemBalance.Items.First(i=>i.Starter==0).Id;game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.enabled=false;n.Story.open=null;n.Story.target=null;n.Story.queue=Array.Empty<string>();n.Story.seen=NarrativeCatalog.Dialogues.Select(x=>x.Id).ToArray();n.Story.tutorial="skipped";n.Retention.aiName="AURA";n.Credits=ScientificNumber.From(50000);n.Hardware[0]=10;n.Charge=96;n.Data=ScientificNumber.From(1000000);n.Workshop.starterGift=true;n.Workshop.components=Enumerable.Repeat(500L,ItemBalance.ComponentIds.Length).ToArray();n.Workshop.learned=Enumerable.Repeat(true,ItemBalance.Items.Length).ToArray();n.Workshop.inventory=new[]{new ItemInstance{id="prepared-a",type=type,level=1},new ItemInstance{id="prepared-b",type=type,level=1}};return n;});game.Show("hardware");yield return null;game.Audio.Unlock();yield return null;yield return null;Assert.That(game.State.Story.open,Is.Null);Assert.That(GameObject.Find("AutomaticMira"),Is.Null,"No dialogue may cover the capture");}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  static void Press(Button button,bool down){Assert.That(button.interactable,Is.True,button.name);var e=new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left};if(down)ExecuteEvents.Execute(button.gameObject,e,ExecuteEvents.pointerDownHandler);else ExecuteEvents.Execute(button.gameObject,e,ExecuteEvents.pointerUpHandler);if(!down)ExecuteEvents.Execute(button.gameObject,e,ExecuteEvents.pointerClickHandler);}
  void Tap(int i){var r=(RectTransform)game.TapButton.transform.parent;var p=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(new Vector2((i-1)*28,8)));var e=new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left,position=p,pressPosition=p};ExecuteEvents.Execute(game.TapButton.gameObject,e,ExecuteEvents.pointerDownHandler);ExecuteEvents.Execute(game.TapButton.gameObject,e,ExecuteEvents.pointerUpHandler);ExecuteEvents.Execute(game.TapButton.gameObject,e,ExecuteEvents.pointerClickHandler);}
  IEnumerator Record(string name,int count,Action<int> action){int start=frame;for(int i=0;i<count;i++){action(i);times.Add(Time.realtimeSinceStartup);WorkshopTests.Capture(390,844,Frames+"/"+(frame++).ToString("D4")+".png");yield return new WaitForSecondsRealtime(.05f);}segments.Add(name+" "+start+" "+(frame-1));}
  [UnityTest]public IEnumerator RecordFiveActualActionsInOrder(){Directory.CreateDirectory(Frames);frame=0;times.Clear();segments.Clear();var existingListener=game.GetComponent<AudioListener>();if(existingListener!=null)existingListener.enabled=false;var listenerNode=new GameObject("ReviewMixedListener",typeof(AudioListener));listenerNode.transform.SetParent(game.transform);var audio=listenerNode.AddComponent<ReviewAudioCapture>();audio.Begin();
   yield return Record("01-tap-overdrive",85,i=>{if(i==14||i==28||i==42||i==56)Tap(i/14-1);});Assert.That(game.State.Lifetime.taps,Is.EqualTo(4));Assert.That(game.State.Overdrives,Is.EqualTo(1));
   yield return Record("02-hardware",65,i=>{var button=GameObject.Find("hardware-calculator").GetComponentsInChildren<Button>().First(b=>b.name=="HardwarePurchase");if(i==15)Press(button,true);if(i==19){var before=game.State.Credits;var cost=Game.HardwareCost(game.State,0,1);Press(button,false);Assert.That(game.State.Credits.CompareTo(before),Is.LessThan(0),"Net debit despite elapsed production tick inside Act");Assert.That(Game.HardwareCost(game.State,0,1).CompareTo(cost),Is.GreaterThan(0));var saved=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(saved.State.Hardware[0],Is.EqualTo(11));}});Assert.That(game.State.Hardware[0],Is.EqualTo(11));var income=Game.Income(game.State);
   game.ItemsTab.onClick.Invoke();yield return null;var ui=game.WorkshopView;ui.SelectRecipe(Workshop.Index(type));yield return null;var q=Workshop.Quote(game.State,type);var stock=(long[])game.State.Workshop.components.Clone();
   yield return Record("03-craft",90,i=>{if(i==15)Press(ui.Primary,true);if(i==19){Press(ui.Primary,false);Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(3));for(int c=0;c<stock.Length;c++)Assert.That(game.State.Workshop.components[c],Is.EqualTo(stock[c]-(long)q.Components[c]));Assert.That(ui.Forge.FlightCount,Is.EqualTo(q.Components.Count(n=>n>0)));var persisted=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(persisted.State.Workshop.inventory.Length,Is.EqualTo(3),"Saved before motion ends");}});Assert.That(ui.Forge.IsAnimating,Is.False);Assert.That(ui.Forge.Inputs.Count(p=>p.gameObject.activeSelf),Is.EqualTo(q.Components.Count(n=>n>0)),"Unused material sockets stay hidden after completion");
   ui.ChangeMode("fusion");yield return null;string[] ids=game.State.Workshop.inventory.Select(x=>x.id).ToArray();foreach(var id in ids){GameObject.Find("item-"+id).GetComponentInChildren<ItemPortrait>().Button.onClick.Invoke();yield return null;}var expected=Workshop.FusionResult(game.State,ids);Assert.That(expected,Is.Not.Null);
   yield return Record("04-fusion",90,i=>{if(i==15)Press(ui.Primary,true);if(i==19){Press(ui.Primary,false);Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(1));Assert.That(ui.Forge.FlightCount,Is.EqualTo(3));Assert.That(ui.Forge.Result.Item.id,Is.EqualTo(expected.id));}});Assert.That(ui.Forge.IsAnimating,Is.False);Assert.That(ui.Forge.Result.Item.rarity,Is.EqualTo(1));Assert.That(ui.Forge.Result.Frame.color,Is.EqualTo(ItemPortrait.RarityColor(1)));
   ui.ChangeMode("inventory");yield return null;GameObject.Find("item-"+expected.id).GetComponentInChildren<ItemPortrait>().Button.onClick.Invoke();yield return new WaitForSecondsRealtime(.45f);string chosen=Workshop.EquipmentSlot(game.State,expected.id);
   yield return Record("05-equip",85,i=>{var b=ui.DetailActions.GetComponentsInChildren<Button>().FirstOrDefault(x=>x.name=="equip-"+chosen);if(i==15)Press(b,true);if(i==19){Press(b,false);Assert.That(game.State.Workshop.equipped.Contains(expected.id),Is.True);Assert.That(ui.GetComponent<EquipFlight>().IsAnimating,Is.True);}});Assert.That(ui.GetComponent<EquipFlight>().IsAnimating,Is.False);Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(1));Assert.That(game.State.Lifetime.itemsFused,Is.EqualTo(1));var load=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(load.Writable,Is.True);Assert.That(load.State.Workshop.equipped.Contains(expected.id),Is.True);Assert.That(load.State.Legacy.prepared,Is.True);
   audio.Save(Frames);File.WriteAllLines(Frames+"/times.txt",times.Select(t=>t.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));File.WriteAllLines(Frames+"/segments.txt",segments);Debug.Log("FIVE_ACTIONS persisted craft=1 fusion=1 hardware=1 taps=4 equip="+chosen+" incomeBeforeEquip="+income+" incomeAfter="+Game.Income(game.State));
  }
  [UnityTest]public IEnumerator ChromeAndActionsAtMobileSizes(){string output="/tmp/idle-design4-review";Directory.CreateDirectory(output);foreach(var language in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",language));game.Show("hardware");yield return new WaitForSecondsRealtime(.45f);var safe=game.GetComponent<MobileShell>().Laboratory.GetComponentInParent<SafeArea>().transform;Assert.That(safe.Find("Resources").GetComponent<Image>().sprite,Is.Null);foreach(var tab in safe.Find("Tabs").GetComponentsInChildren<Button>())Assert.That(tab.GetComponent<Image>().sprite,Is.Null);foreach(var width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/labor-"+language+"-"+width+".png");yield return null;}game.ItemsTab.onClick.Invoke();yield return null;var ui=game.WorkshopView;ui.SelectRecipe(Workshop.Index(type));ui.Primary.onClick.Invoke();yield return new WaitForSecondsRealtime(2.4f);foreach(var width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/craft-"+language+"-"+width+".png");yield return null;}ui.ChangeMode("inventory");yield return null;ui.OpenItem(game.State.Workshop.inventory.Last().id);yield return new WaitForSecondsRealtime(.45f);foreach(var width in new[]{320,390,430}){WorkshopTests.Capture(width,width==320?568:width==390?844:932,output+"/detail-"+language+"-"+width+".png");yield return null;}}
  }
  [UnityTest]public IEnumerator RapidRepeatCancelReducedAndReloadStayExactlyOnce(){game.ItemsTab.onClick.Invoke();yield return null;var ui=game.WorkshopView;ui.SelectRecipe(Workshop.Index(type));for(int i=0;i<5;i++)ui.Primary.onClick.Invoke();Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(7));Assert.That(UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Count(t=>t.name.StartsWith("ComponentFlight")),Is.LessThanOrEqualTo(20));ui.ChangeMode("inventory");yield return null;Assert.That(ui.Forge.IsAnimating,Is.False);ui.OpenItem("prepared-a");ui.DetailActions.GetComponentsInChildren<Button>().First(b=>b.name.StartsWith("equip-")).onClick.Invoke();game.HardwareTab.onClick.Invoke();yield return new WaitForSecondsRealtime(.8f);Assert.That(GameObject.Find("EquipmentFlightLayer"),Is.Null);game.Act(s=>{var n=s.Copy();n.Settings.effects=false;n.Workshop.reducedMotion=true;return n;});game.ItemsTab.onClick.Invoke();yield return null;ui=game.WorkshopView;ui.SelectRecipe(Workshop.Index(type));ui.Primary.onClick.Invoke();Assert.That(ui.Forge.IsAnimating,Is.False);Assert.That(ui.Forge.Result.Item.id,Is.EqualTo(game.State.Workshop.inventory.Last().id));ui.ChangeMode("inventory");ui.OpenItem("prepared-b");ui.DetailActions.GetComponentsInChildren<Button>().First(b=>b.name.StartsWith("equip-")).onClick.Invoke();Assert.That(ui.GetComponent<EquipFlight>().IsAnimating,Is.False);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(8));Assert.That(game.State.Workshop.equipped.Contains("prepared-b"),Is.True);Assert.That(game.State.Settings.effects,Is.False);}
 }
}
